-- Finance organ -- generated by noctusai_lib.domain.finance.sql (do not hand-edit)

SET search_path = monica, public;

-- Accounts (bank / cash / gateway wallets). One gateway account per (org, gateway).
CREATE TABLE IF NOT EXISTS monica.fin_accounts (
    id                    UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    org_id                UUID NOT NULL,
    name                  TEXT NOT NULL,
    kind                  TEXT NOT NULL CHECK (kind IN ('checking', 'savings', 'cash', 'gateway', 'credit_card', 'investment')),
    bank_code             TEXT,
    agency                TEXT,
    number                TEXT,
    opening_balance_cents BIGINT NOT NULL DEFAULT 0,
    opening_date          DATE,
    gateway               TEXT,
    active                BOOLEAN NOT NULL DEFAULT true,
    created_at            TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at            TIMESTAMPTZ NOT NULL DEFAULT now(),
    CHECK (kind <> 'gateway' OR gateway IS NOT NULL)
);
CREATE UNIQUE INDEX IF NOT EXISTS uq_fin_accounts_gateway ON monica.fin_accounts (org_id, gateway)
    WHERE kind = 'gateway';
CREATE INDEX IF NOT EXISTS idx_fin_accounts_org ON monica.fin_accounts (org_id);
-- Accounting code (E21): the contador's reduced account code for this bank/cash/gateway account (free text, optional);
-- the Domínio export refuses to run while a used account has none.
ALTER TABLE monica.fin_accounts ADD COLUMN IF NOT EXISTS accounting_code TEXT;
ALTER TABLE monica.fin_accounts ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "fin_accounts_select_own_org" ON monica.fin_accounts;
CREATE POLICY "fin_accounts_select_own_org" ON monica.fin_accounts FOR SELECT TO authenticated
  USING (org_id = (SELECT public.current_org_id_for('monica')));
DROP POLICY IF EXISTS "service_role_bypass" ON monica.fin_accounts;
CREATE POLICY "service_role_bypass" ON monica.fin_accounts FOR ALL TO service_role USING (true) WITH CHECK (true);

-- Categories (tree). Unique (org, parent, lower(name)); defaults are seeded per org on first use.
CREATE TABLE IF NOT EXISTS monica.fin_categories (
    id          UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    org_id      UUID NOT NULL,
    parent_id   UUID REFERENCES monica.fin_categories(id) ON DELETE RESTRICT,
    name        TEXT NOT NULL,
    direction   TEXT NOT NULL CHECK (direction IN ('income', 'expense', 'transfer')),
    is_default  BOOLEAN NOT NULL DEFAULT false,
    active      BOOLEAN NOT NULL DEFAULT true,
    created_at  TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at  TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE UNIQUE INDEX IF NOT EXISTS uq_fin_categories_name ON monica.fin_categories
    (org_id, COALESCE(parent_id, '00000000-0000-0000-0000-000000000000'::uuid), lower(name));
CREATE INDEX IF NOT EXISTS idx_fin_categories_parent ON monica.fin_categories (parent_id);
-- DRE mapping (CONTRACT §10.3 / §10.5): additive and re-runnable (tables created by an older generator gain the columns).
-- dre_line NULL = unclassified (shown in its own block with a warning); behavior NULL = the line's default;
-- is_das marks the category that holds the DAS payable (routed by the store's tax regime).
ALTER TABLE monica.fin_categories ADD COLUMN IF NOT EXISTS dre_line TEXT
    CHECK (dre_line IN ('gross_revenue', 'deductions', 'cost_of_sales', 'selling_expenses', 'administrative_expenses', 'other_operating', 'financial_revenue', 'financial_expenses', 'income_taxes', 'unclassified'));
ALTER TABLE monica.fin_categories ADD COLUMN IF NOT EXISTS behavior TEXT
    CHECK (behavior IN ('variable', 'fixed'));
ALTER TABLE monica.fin_categories ADD COLUMN IF NOT EXISTS is_das BOOLEAN NOT NULL DEFAULT false;
-- E21: the contador's reduced account code (free text, optional -- only the Domínio export needs it) and the MEI
-- activity group (comércio / indústria / serviços) the Relatório Mensal de Receitas Brutas splits revenue by.
ALTER TABLE monica.fin_categories ADD COLUMN IF NOT EXISTS accounting_code TEXT;
ALTER TABLE monica.fin_categories ADD COLUMN IF NOT EXISTS activity_kind TEXT
    CHECK (activity_kind IN ('comercio', 'industria', 'servicos'));
ALTER TABLE monica.fin_categories ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "fin_categories_select_own_org" ON monica.fin_categories;
CREATE POLICY "fin_categories_select_own_org" ON monica.fin_categories FOR SELECT TO authenticated
  USING (org_id = (SELECT public.current_org_id_for('monica')));
DROP POLICY IF EXISTS "service_role_bypass" ON monica.fin_categories;
CREATE POLICY "service_role_bypass" ON monica.fin_categories FOR ALL TO service_role USING (true) WITH CHECK (true);

-- Cost centers (code unique per org).
CREATE TABLE IF NOT EXISTS monica.fin_cost_centers (
    id          UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    org_id      UUID NOT NULL,
    code        TEXT NOT NULL,
    name        TEXT NOT NULL,
    active      BOOLEAN NOT NULL DEFAULT true,
    created_at  TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at  TIMESTAMPTZ NOT NULL DEFAULT now(),
    UNIQUE (org_id, code)
);
ALTER TABLE monica.fin_cost_centers ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "fin_cost_centers_select_own_org" ON monica.fin_cost_centers;
CREATE POLICY "fin_cost_centers_select_own_org" ON monica.fin_cost_centers FOR SELECT TO authenticated
  USING (org_id = (SELECT public.current_org_id_for('monica')));
DROP POLICY IF EXISTS "service_role_bypass" ON monica.fin_cost_centers;
CREATE POLICY "service_role_bypass" ON monica.fin_cost_centers FOR ALL TO service_role USING (true) WITH CHECK (true);

-- Recurrences: `template` is the entry shape; generation is idempotent on (recurrence_id, due_date).
CREATE TABLE IF NOT EXISTS monica.fin_recurrences (
    id          UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    org_id      UUID NOT NULL,
    template    JSONB NOT NULL,
    frequency   TEXT NOT NULL CHECK (frequency IN ('daily', 'weekly', 'biweekly', 'monthly', 'bimonthly', 'quarterly', 'semiannual', 'annual')),
    next_date   DATE NOT NULL,
    end_date    DATE,
    active      BOOLEAN NOT NULL DEFAULT true,
    created_at  TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at  TIMESTAMPTZ NOT NULL DEFAULT now(),
    CHECK (end_date IS NULL OR end_date >= next_date OR active = false)
);
CREATE INDEX IF NOT EXISTS idx_fin_recurrences_due ON monica.fin_recurrences (next_date) WHERE active;
ALTER TABLE monica.fin_recurrences ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "fin_recurrences_select_own_org" ON monica.fin_recurrences;
CREATE POLICY "fin_recurrences_select_own_org" ON monica.fin_recurrences FOR SELECT TO authenticated
  USING (org_id = (SELECT public.current_org_id_for('monica')));
DROP POLICY IF EXISTS "service_role_bypass" ON monica.fin_recurrences;
CREATE POLICY "service_role_bypass" ON monica.fin_recurrences FOR ALL TO service_role USING (true) WITH CHECK (true);

-- Entries: payables / receivables. `overdue` is NEVER stored (computed on read). `settled_cents` is derived from unreversed settlements.
CREATE TABLE IF NOT EXISTS monica.fin_entries (
    id                   UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    org_id               UUID NOT NULL,
    direction            TEXT NOT NULL CHECK (direction IN ('payable', 'receivable')),
    status               TEXT NOT NULL DEFAULT 'open' CHECK (status IN ('open', 'partial', 'paid', 'cancelled')),
    description          TEXT NOT NULL,
    counterparty_name    TEXT,
    counterparty_doc     TEXT,
    category_id          UUID REFERENCES monica.fin_categories(id) ON DELETE RESTRICT,
    cost_center_id       UUID REFERENCES monica.fin_cost_centers(id) ON DELETE RESTRICT,
    expected_account_id  UUID REFERENCES monica.fin_accounts(id) ON DELETE RESTRICT,
    competence_month     DATE NOT NULL CHECK (EXTRACT(DAY FROM competence_month) = 1),
    due_date             DATE NOT NULL,
    amount_cents         BIGINT NOT NULL CHECK (amount_cents > 0),
    settled_cents        BIGINT NOT NULL DEFAULT 0 CHECK (settled_cents >= 0 AND settled_cents <= amount_cents),
    source               TEXT NOT NULL DEFAULT 'manual' CHECK (source IN ('manual', 'recurrence', 'installment', 'commerce_order', 'contracts', 'import', 'external', 'purchasing')),
    source_ref           TEXT,
    recurrence_id        UUID REFERENCES monica.fin_recurrences(id) ON DELETE SET NULL,
    installment_group_id UUID,
    installment_n        INTEGER,
    installment_total    INTEGER,
    notes                TEXT,
    created_at           TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at           TIMESTAMPTZ NOT NULL DEFAULT now(),
    CHECK (
        (installment_group_id IS NULL AND installment_n IS NULL AND installment_total IS NULL)
        OR (installment_group_id IS NOT NULL AND installment_n BETWEEN 1 AND installment_total
            AND installment_total >= 2)
    )
);
CREATE UNIQUE INDEX IF NOT EXISTS uq_fin_entries_source_ref ON monica.fin_entries (org_id, source, source_ref)
    WHERE source_ref IS NOT NULL;
CREATE UNIQUE INDEX IF NOT EXISTS uq_fin_entries_recurrence_due ON monica.fin_entries (recurrence_id, due_date)
    WHERE recurrence_id IS NOT NULL;
CREATE UNIQUE INDEX IF NOT EXISTS uq_fin_entries_installment ON monica.fin_entries (installment_group_id, installment_n)
    WHERE installment_group_id IS NOT NULL;
CREATE INDEX IF NOT EXISTS idx_fin_entries_org_due ON monica.fin_entries (org_id, due_date);
CREATE INDEX IF NOT EXISTS idx_fin_entries_org_status ON monica.fin_entries (org_id, status, due_date);
CREATE INDEX IF NOT EXISTS idx_fin_entries_org_competence ON monica.fin_entries (org_id, competence_month);
CREATE INDEX IF NOT EXISTS idx_fin_entries_category ON monica.fin_entries (category_id);
-- E21: did this sale carry a nota fiscal? NULL = not informed (the MEI report counts it as "sem nota" and warns).
ALTER TABLE monica.fin_entries ADD COLUMN IF NOT EXISTS has_invoice BOOLEAN;
-- Entry source vocabulary: re-stated so tables created before a source existed accept it.
ALTER TABLE monica.fin_entries DROP CONSTRAINT IF EXISTS fin_entries_source_check;
ALTER TABLE monica.fin_entries ADD CONSTRAINT fin_entries_source_check CHECK (source IN ('manual', 'recurrence', 'installment', 'commerce_order', 'contracts', 'import', 'external', 'purchasing'));
ALTER TABLE monica.fin_entries ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "fin_entries_select_own_org" ON monica.fin_entries;
CREATE POLICY "fin_entries_select_own_org" ON monica.fin_entries FOR SELECT TO authenticated
  USING (org_id = (SELECT public.current_org_id_for('monica')));
DROP POLICY IF EXISTS "service_role_bypass" ON monica.fin_entries;
CREATE POLICY "service_role_bypass" ON monica.fin_entries FOR ALL TO service_role USING (true) WITH CHECK (true);

-- Statement imports (slice D service). sha256 unique per account: re-importing a file is a 409.
CREATE TABLE IF NOT EXISTS monica.fin_statement_imports (
    id            UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    org_id        UUID NOT NULL,
    account_id    UUID NOT NULL REFERENCES monica.fin_accounts(id) ON DELETE RESTRICT,
    format        TEXT NOT NULL CHECK (format IN ('ofx', 'csv')),
    filename      TEXT NOT NULL,
    sha256        TEXT NOT NULL,
    period_start  DATE,
    period_end    DATE,
    imported_by   UUID,
    at            TIMESTAMPTZ NOT NULL DEFAULT now(),
    UNIQUE (account_id, sha256)
);
CREATE INDEX IF NOT EXISTS idx_fin_statement_imports_org ON monica.fin_statement_imports (org_id, at DESC);
ALTER TABLE monica.fin_statement_imports ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "fin_statement_imports_select_own_org" ON monica.fin_statement_imports;
CREATE POLICY "fin_statement_imports_select_own_org" ON monica.fin_statement_imports FOR SELECT TO authenticated
  USING (org_id = (SELECT public.current_org_id_for('monica')));
DROP POLICY IF EXISTS "service_role_bypass" ON monica.fin_statement_imports;
CREATE POLICY "service_role_bypass" ON monica.fin_statement_imports FOR ALL TO service_role USING (true) WITH CHECK (true);

-- Statement lines (slice D service). `ledger_id` FK is added after the ledger exists (cycle).
CREATE TABLE IF NOT EXISTS monica.fin_statement_lines (
    id                   UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    org_id               UUID NOT NULL,
    import_id            UUID NOT NULL REFERENCES monica.fin_statement_imports(id) ON DELETE CASCADE,
    account_id           UUID NOT NULL REFERENCES monica.fin_accounts(id) ON DELETE RESTRICT,
    posted_on            DATE NOT NULL,
    amount_cents         BIGINT NOT NULL CHECK (amount_cents <> 0),
    description          TEXT NOT NULL DEFAULT '',
    fitid                TEXT NOT NULL,
    match_status         TEXT NOT NULL DEFAULT 'unmatched' CHECK (match_status IN ('unmatched', 'suggested', 'matched', 'ignored')),
    ledger_id            UUID,
    suggested_entry_id   UUID REFERENCES monica.fin_entries(id) ON DELETE SET NULL,
    UNIQUE (account_id, fitid)
);
CREATE UNIQUE INDEX IF NOT EXISTS uq_fin_statement_lines_ledger ON monica.fin_statement_lines (ledger_id)
    WHERE ledger_id IS NOT NULL;
CREATE INDEX IF NOT EXISTS idx_fin_statement_lines_import ON monica.fin_statement_lines (import_id);
CREATE INDEX IF NOT EXISTS idx_fin_statement_lines_org_status ON monica.fin_statement_lines (org_id, match_status);
ALTER TABLE monica.fin_statement_lines ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "fin_statement_lines_select_own_org" ON monica.fin_statement_lines;
CREATE POLICY "fin_statement_lines_select_own_org" ON monica.fin_statement_lines FOR SELECT TO authenticated
  USING (org_id = (SELECT public.current_org_id_for('monica')));
DROP POLICY IF EXISTS "service_role_bypass" ON monica.fin_statement_lines;
CREATE POLICY "service_role_bypass" ON monica.fin_statement_lines FOR ALL TO service_role USING (true) WITH CHECK (true);

-- Settlements: payments / refunds against an entry. NEVER deleted -- a reversal sets reversed_* and books opposite ledger rows.
CREATE TABLE IF NOT EXISTS monica.fin_settlements (
    id                UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    org_id            UUID NOT NULL,
    entry_id          UUID NOT NULL REFERENCES monica.fin_entries(id) ON DELETE RESTRICT,
    account_id        UUID NOT NULL REFERENCES monica.fin_accounts(id) ON DELETE RESTRICT,
    kind              TEXT NOT NULL CHECK (kind IN ('payment', 'refund')),
    settled_on        DATE NOT NULL,
    amount_cents      BIGINT NOT NULL CHECK (amount_cents > 0),
    fee_cents         BIGINT NOT NULL DEFAULT 0 CHECK (fee_cents >= 0),
    method            TEXT,
    external_ref      TEXT,
    statement_line_id UUID REFERENCES monica.fin_statement_lines(id) ON DELETE SET NULL,
    created_by        UUID,
    created_at        TIMESTAMPTZ NOT NULL DEFAULT now(),
    reversed_at       TIMESTAMPTZ,
    reversed_by       UUID,
    reversal_reason   TEXT,
    CHECK ((reversed_at IS NULL) = (reversal_reason IS NULL))
);
CREATE UNIQUE INDEX IF NOT EXISTS uq_fin_settlements_external ON monica.fin_settlements (org_id, kind, external_ref)
    WHERE external_ref IS NOT NULL;
CREATE INDEX IF NOT EXISTS idx_fin_settlements_entry ON monica.fin_settlements (entry_id);
CREATE INDEX IF NOT EXISTS idx_fin_settlements_org_date ON monica.fin_settlements (org_id, settled_on);
ALTER TABLE monica.fin_settlements ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "fin_settlements_select_own_org" ON monica.fin_settlements;
CREATE POLICY "fin_settlements_select_own_org" ON monica.fin_settlements FOR SELECT TO authenticated
  USING (org_id = (SELECT public.current_org_id_for('monica')));
DROP POLICY IF EXISTS "service_role_bypass" ON monica.fin_settlements;
CREATE POLICY "service_role_bypass" ON monica.fin_settlements FOR ALL TO service_role USING (true) WITH CHECK (true);

-- Ledger (append-only): the money that actually moved on an account. Transfers = two rows sharing transfer_group. A reversal row points at the row it reverses.
CREATE TABLE IF NOT EXISTS monica.fin_ledger (
    id             UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    org_id         UUID NOT NULL,
    account_id     UUID NOT NULL REFERENCES monica.fin_accounts(id) ON DELETE RESTRICT,
    occurred_on    DATE NOT NULL,
    direction      TEXT NOT NULL CHECK (direction IN ('in', 'out')),
    amount_cents   BIGINT NOT NULL CHECK (amount_cents > 0),
    origin         TEXT NOT NULL CHECK (origin IN ('settlement', 'fee', 'transfer', 'adjustment', 'opening')),
    settlement_id  UUID REFERENCES monica.fin_settlements(id) ON DELETE RESTRICT,
    transfer_group UUID,
    reverses_id    UUID REFERENCES monica.fin_ledger(id) ON DELETE RESTRICT,
    description    TEXT,
    created_at     TIMESTAMPTZ NOT NULL DEFAULT now(),
    CHECK (origin <> 'transfer' OR transfer_group IS NOT NULL),
    CHECK (origin NOT IN ('settlement', 'fee') OR settlement_id IS NOT NULL)
);
CREATE UNIQUE INDEX IF NOT EXISTS uq_fin_ledger_settlement_origin ON monica.fin_ledger (settlement_id, origin)
    WHERE settlement_id IS NOT NULL AND reverses_id IS NULL;
CREATE UNIQUE INDEX IF NOT EXISTS uq_fin_ledger_reverses ON monica.fin_ledger (reverses_id)
    WHERE reverses_id IS NOT NULL;
CREATE INDEX IF NOT EXISTS idx_fin_ledger_account_date ON monica.fin_ledger (org_id, account_id, occurred_on);
CREATE INDEX IF NOT EXISTS idx_fin_ledger_transfer ON monica.fin_ledger (transfer_group)
    WHERE transfer_group IS NOT NULL;
DO $fin_fk$
BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM pg_constraint
        WHERE conname = 'fin_statement_lines_ledger_id_fkey' AND conrelid = 'monica.fin_statement_lines'::regclass
    ) THEN
        ALTER TABLE monica.fin_statement_lines
            ADD CONSTRAINT fin_statement_lines_ledger_id_fkey
            FOREIGN KEY (ledger_id) REFERENCES monica.fin_ledger(id) ON DELETE SET NULL;
    END IF;
END
$fin_fk$;
ALTER TABLE monica.fin_ledger ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "fin_ledger_select_own_org" ON monica.fin_ledger;
CREATE POLICY "fin_ledger_select_own_org" ON monica.fin_ledger FOR SELECT TO authenticated
  USING (org_id = (SELECT public.current_org_id_for('monica')));
DROP POLICY IF EXISTS "service_role_bypass" ON monica.fin_ledger;
CREATE POLICY "service_role_bypass" ON monica.fin_ledger FOR ALL TO service_role USING (true) WITH CHECK (true);

-- Attachments: private bucket objects, keys `<org_id>/entries/<entry_id>/<id>.<ext>` (server-generated).
CREATE TABLE IF NOT EXISTS monica.fin_attachments (
    id            UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    org_id        UUID NOT NULL,
    entry_id      UUID NOT NULL REFERENCES monica.fin_entries(id) ON DELETE CASCADE,
    storage_path  TEXT NOT NULL,
    filename      TEXT NOT NULL,
    content_type  TEXT NOT NULL,
    size_bytes    INTEGER NOT NULL CHECK (size_bytes >= 0),
    uploaded_by   UUID,
    at            TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS idx_fin_attachments_entry ON monica.fin_attachments (entry_id);
ALTER TABLE monica.fin_attachments ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "fin_attachments_select_own_org" ON monica.fin_attachments;
CREATE POLICY "fin_attachments_select_own_org" ON monica.fin_attachments FOR SELECT TO authenticated
  USING (org_id = (SELECT public.current_org_id_for('monica')));
DROP POLICY IF EXISTS "service_role_bypass" ON monica.fin_attachments;
CREATE POLICY "service_role_bypass" ON monica.fin_attachments FOR ALL TO service_role USING (true) WITH CHECK (true);

-- Gateway sync cursor (slice D service): one row per gateway account.
CREATE TABLE IF NOT EXISTS monica.fin_gateway_sync (
    account_id      UUID PRIMARY KEY REFERENCES monica.fin_accounts(id) ON DELETE CASCADE,
    org_id          UUID NOT NULL,
    cursor          TEXT,
    last_synced_at  TIMESTAMPTZ,
    last_error      TEXT
);
CREATE INDEX IF NOT EXISTS idx_fin_gateway_sync_org ON monica.fin_gateway_sync (org_id);
ALTER TABLE monica.fin_gateway_sync ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "fin_gateway_sync_select_own_org" ON monica.fin_gateway_sync;
CREATE POLICY "fin_gateway_sync_select_own_org" ON monica.fin_gateway_sync FOR SELECT TO authenticated
  USING (org_id = (SELECT public.current_org_id_for('monica')));
DROP POLICY IF EXISTS "service_role_bypass" ON monica.fin_gateway_sync;
CREATE POLICY "service_role_bypass" ON monica.fin_gateway_sync FOR ALL TO service_role USING (true) WITH CHECK (true);

-- DRE settings (CONTRACT §10.5): ONE row per org. The per-store mapping of every provisional accounting choice is DATA so an accountant changes it without touching money records. `choice_meta` is `{<choice>: {provisional, confirmed_by, confirmed_at, note}}` -- absent = provisional (the default).
CREATE TABLE IF NOT EXISTS monica.fin_dre_settings (
    id                         UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    org_id                     UUID NOT NULL UNIQUE,
    tax_regime                 TEXT NOT NULL DEFAULT 'unknown' CHECK (tax_regime IN ('mei', 'simples', 'presumido', 'unknown')),
    das_split_irpj_csll        BOOLEAN NOT NULL DEFAULT false,
    das_irpj_csll_share_bps    INTEGER NOT NULL DEFAULT 0 CHECK (das_irpj_csll_share_bps BETWEEN 0 AND 10000),
    gateway_fee_line           TEXT NOT NULL DEFAULT 'selling_expenses' CHECK (gateway_fee_line IN ('gross_revenue', 'deductions', 'cost_of_sales', 'selling_expenses', 'administrative_expenses', 'other_operating', 'financial_revenue', 'financial_expenses', 'income_taxes')),
    anticipation_fee_line      TEXT NOT NULL DEFAULT 'financial_expenses' CHECK (anticipation_fee_line IN ('gross_revenue', 'deductions', 'cost_of_sales', 'selling_expenses', 'administrative_expenses', 'other_operating', 'financial_revenue', 'financial_expenses', 'income_taxes')),
    chargeback_line            TEXT NOT NULL DEFAULT 'deductions' CHECK (chargeback_line IN ('gross_revenue', 'deductions', 'cost_of_sales', 'selling_expenses', 'administrative_expenses', 'other_operating', 'financial_revenue', 'financial_expenses', 'income_taxes')),
    chargeback_fee_line        TEXT NOT NULL DEFAULT 'selling_expenses' CHECK (chargeback_fee_line IN ('gross_revenue', 'deductions', 'cost_of_sales', 'selling_expenses', 'administrative_expenses', 'other_operating', 'financial_revenue', 'financial_expenses', 'income_taxes')),
    installment_interest_line  TEXT NOT NULL DEFAULT 'gross_revenue' CHECK (installment_interest_line IN ('gross_revenue', 'deductions', 'cost_of_sales', 'selling_expenses', 'administrative_expenses', 'other_operating', 'financial_revenue', 'financial_expenses', 'income_taxes')),
    choice_meta                JSONB NOT NULL DEFAULT '{}'::jsonb,
    updated_by                 UUID,
    created_at                 TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at                 TIMESTAMPTZ NOT NULL DEFAULT now()
);
ALTER TABLE monica.fin_dre_settings ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "fin_dre_settings_select_own_org" ON monica.fin_dre_settings;
CREATE POLICY "fin_dre_settings_select_own_org" ON monica.fin_dre_settings FOR SELECT TO authenticated
  USING (org_id = (SELECT public.current_org_id_for('monica')));
DROP POLICY IF EXISTS "service_role_bypass" ON monica.fin_dre_settings;
CREATE POLICY "service_role_bypass" ON monica.fin_dre_settings FOR ALL TO service_role USING (true) WITH CHECK (true);

-- Budgets (E21): the planned amount per (category, month); the report compares it with the DRE-basis actual. One row per (org, category, month).
CREATE TABLE IF NOT EXISTS monica.fin_budgets (
    id            UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    org_id        UUID NOT NULL,
    category_id   UUID NOT NULL REFERENCES monica.fin_categories(id) ON DELETE CASCADE,
    month         DATE NOT NULL CHECK (EXTRACT(DAY FROM month) = 1),
    amount_cents  BIGINT NOT NULL CHECK (amount_cents >= 0),
    created_at    TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at    TIMESTAMPTZ NOT NULL DEFAULT now(),
    UNIQUE (org_id, category_id, month)
);
CREATE INDEX IF NOT EXISTS idx_fin_budgets_org_month ON monica.fin_budgets (org_id, month);
ALTER TABLE monica.fin_budgets ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "fin_budgets_select_own_org" ON monica.fin_budgets;
CREATE POLICY "fin_budgets_select_own_org" ON monica.fin_budgets FOR SELECT TO authenticated
  USING (org_id = (SELECT public.current_org_id_for('monica')));
DROP POLICY IF EXISTS "service_role_bypass" ON monica.fin_budgets;
CREATE POLICY "service_role_bypass" ON monica.fin_budgets FOR ALL TO service_role USING (true) WITH CHECK (true);

-- Settle under a row lock: the balance is checked and the settlement inserted in ONE transaction.
CREATE OR REPLACE FUNCTION monica.fin_settle_entry_locked(p_org_id UUID, p_entry_id UUID, p_row JSONB) RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, monica, pg_temp
AS $fn$
DECLARE
    v_entry   monica.fin_entries%ROWTYPE;
    v_row     monica.fin_settlements%ROWTYPE;
    v_settled BIGINT;
    v_amount  BIGINT := (p_row->>'amount_cents')::BIGINT;
    v_kind    TEXT := p_row->>'kind';
BEGIN
    IF v_amount IS NULL OR v_amount <= 0 THEN
        RETURN jsonb_build_object('status', 'refused', 'code', 'valor_invalido');
    END IF;
    IF v_kind IS NULL OR v_kind NOT IN ('payment', 'refund') THEN
        RETURN jsonb_build_object('status', 'refused', 'code', 'tipo_invalido');
    END IF;
    SELECT * INTO v_entry FROM monica.fin_entries WHERE id = p_entry_id AND org_id = p_org_id FOR UPDATE;
    IF NOT FOUND THEN
        RETURN jsonb_build_object('status', 'not_found');
    END IF;
    IF v_entry.status = 'cancelled' THEN
        RETURN jsonb_build_object('status', 'refused', 'code', 'lancamento_cancelado');
    END IF;
    SELECT COALESCE(SUM(CASE WHEN kind = 'payment' THEN amount_cents ELSE -amount_cents END), 0) INTO v_settled
        FROM monica.fin_settlements WHERE entry_id = p_entry_id AND reversed_at IS NULL;
    IF v_kind = 'payment' AND v_amount > v_entry.amount_cents - v_settled THEN
        RETURN jsonb_build_object('status', 'refused', 'code', 'baixa_excede_saldo');
    END IF;
    IF v_kind = 'refund' AND v_amount > v_settled THEN
        RETURN jsonb_build_object('status', 'refused', 'code', 'estorno_excede_pago');
    END IF;
    INSERT INTO monica.fin_settlements
        SELECT * FROM jsonb_populate_record(
            NULL::monica.fin_settlements,
            jsonb_set(jsonb_set(p_row, '{org_id}', to_jsonb(p_org_id::text)), '{entry_id}', to_jsonb(p_entry_id::text))
        )
        RETURNING * INTO v_row;
    RETURN jsonb_build_object('status', 'ok', 'settlement', to_jsonb(v_row));
END;
$fn$;
REVOKE ALL ON FUNCTION monica.fin_settle_entry_locked(UUID, UUID, JSONB) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION monica.fin_settle_entry_locked(UUID, UUID, JSONB) TO service_role;

-- Reverse under the same lock: stamp the settlement and book the opposite ledger rows atomically.
CREATE OR REPLACE FUNCTION monica.fin_reverse_settlement_locked(p_org_id UUID, p_settlement_id UUID, p_reason TEXT, p_user UUID, p_on DATE) RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, monica, pg_temp
AS $fn$
DECLARE
    v_st      monica.fin_settlements%ROWTYPE;
    v_entry   monica.fin_entries%ROWTYPE;
    v_settled BIGINT;
    v_after   BIGINT;
BEGIN
    SELECT * INTO v_st FROM monica.fin_settlements WHERE id = p_settlement_id AND org_id = p_org_id;
    IF NOT FOUND THEN
        RETURN jsonb_build_object('status', 'not_found');
    END IF;
    SELECT * INTO v_entry FROM monica.fin_entries WHERE id = v_st.entry_id AND org_id = p_org_id FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'settlement % has no entry in org %', p_settlement_id, p_org_id USING ERRCODE = 'P0002';
    END IF;
    SELECT * INTO v_st FROM monica.fin_settlements WHERE id = p_settlement_id;
    IF v_st.reversed_at IS NOT NULL THEN
        RETURN jsonb_build_object('status', 'already_reversed');
    END IF;
    SELECT COALESCE(SUM(CASE WHEN kind = 'payment' THEN amount_cents ELSE -amount_cents END), 0) INTO v_settled
        FROM monica.fin_settlements WHERE entry_id = v_entry.id AND reversed_at IS NULL;
    v_after := CASE WHEN v_st.kind = 'payment' THEN v_settled - v_st.amount_cents ELSE v_settled + v_st.amount_cents END;
    IF v_after < 0 OR v_after > v_entry.amount_cents THEN
        RETURN jsonb_build_object('status', 'refused', 'code', 'baixa_com_estorno');
    END IF;
    UPDATE monica.fin_settlements
        SET reversed_at = now(), reversed_by = p_user, reversal_reason = p_reason
        WHERE id = p_settlement_id RETURNING * INTO v_st;
    INSERT INTO monica.fin_ledger (org_id, account_id, occurred_on, direction, amount_cents, origin, description, settlement_id, reverses_id)
        SELECT l.org_id, l.account_id, p_on, CASE l.direction WHEN 'in' THEN 'out' ELSE 'in' END, l.amount_cents, l.origin,
               'Estorno: ' || COALESCE(l.description, ''), l.settlement_id, l.id
        FROM monica.fin_ledger l
        WHERE l.settlement_id = p_settlement_id AND l.reverses_id IS NULL
          AND NOT EXISTS (SELECT 1 FROM monica.fin_ledger r WHERE r.reverses_id = l.id);
    RETURN jsonb_build_object('status', 'ok', 'settlement', to_jsonb(v_st));
END;
$fn$;
REVOKE ALL ON FUNCTION monica.fin_reverse_settlement_locked(UUID, UUID, TEXT, UUID, DATE) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION monica.fin_reverse_settlement_locked(UUID, UUID, TEXT, UUID, DATE) TO service_role;

-- Private finance attachments bucket; object RLS keys on the org_id first path segment.
INSERT INTO storage.buckets (id, name, public)
VALUES ('finance-attachments', 'finance-attachments', false)
ON CONFLICT (id) DO NOTHING;
DROP POLICY IF EXISTS "finance-attachments_storage_select" ON storage.objects;
CREATE POLICY "finance-attachments_storage_select" ON storage.objects FOR SELECT TO authenticated
  USING (bucket_id = 'finance-attachments' AND (storage.foldername(name))[1] = (SELECT public.current_org_id())::text);
DROP POLICY IF EXISTS "finance-attachments_storage_insert" ON storage.objects;
CREATE POLICY "finance-attachments_storage_insert" ON storage.objects FOR INSERT TO authenticated
  WITH CHECK (bucket_id = 'finance-attachments' AND (storage.foldername(name))[1] = (SELECT public.current_org_id())::text);
DROP POLICY IF EXISTS "finance-attachments_storage_update" ON storage.objects;
CREATE POLICY "finance-attachments_storage_update" ON storage.objects FOR UPDATE TO authenticated
  USING (bucket_id = 'finance-attachments' AND (storage.foldername(name))[1] = (SELECT public.current_org_id())::text);
DROP POLICY IF EXISTS "finance-attachments_storage_delete" ON storage.objects;
CREATE POLICY "finance-attachments_storage_delete" ON storage.objects FOR DELETE TO authenticated
  USING (bucket_id = 'finance-attachments' AND (storage.foldername(name))[1] = (SELECT public.current_org_id())::text);
DROP POLICY IF EXISTS "finance-attachments_storage_service" ON storage.objects;
CREATE POLICY "finance-attachments_storage_service" ON storage.objects FOR ALL TO service_role
  USING (bucket_id = 'finance-attachments')
  WITH CHECK (bucket_id = 'finance-attachments');
